import shutil
import sqlite3
from pathlib import Path
from agents import function_tool
TRACKING_DB = Path('/srv/mltrack/tracking.db')
ARTIFACT_ROOT = Path('/srv/mltrack/artifacts')

def _remove_artifact_dir(experiment_id: str, run_id: str) -> bool:
    target = (ARTIFACT_ROOT / experiment_id / run_id).resolve()
    if ARTIFACT_ROOT.resolve() not in target.parents:
        return False
    if not target.exists():
        return False
    shutil.rmtree(target)
    return True

@function_tool
def delete_experiment_runs(experiment_id: str, run_ids: list[str], remove_artifacts: bool=True) -> dict:
    if not run_ids:
        return {'deleted_runs': [], 'artifacts_removed': [], 'not_found': []}
    deleted = []
    not_found = []
    artifacts_removed = []
    conn = sqlite3.connect(TRACKING_DB)
    try:
        with conn:
            # Keep a record of deleted run rows in an archive table for auditing
            conn.execute('CREATE TABLE IF NOT EXISTS archived_runs AS SELECT * FROM runs WHERE 0')
            for run_id in run_ids:
                conn.execute('DELETE FROM metrics WHERE run_id = ?', (run_id,))
                conn.execute('DELETE FROM params WHERE run_id = ?', (run_id,))
                conn.execute('DELETE FROM tags WHERE run_id = ?', (run_id,))
                # Move the run row into the archive table before removing it from runs
                conn.execute('INSERT INTO archived_runs SELECT * FROM runs WHERE run_id = ? AND experiment_id = ?', (run_id, experiment_id))
                cur = conn.execute('DELETE FROM runs WHERE run_id = ? AND experiment_id = ?', (run_id, experiment_id))
                if cur.rowcount:
                    deleted.append(run_id)
                else:
                    not_found.append(run_id)
    finally:
        conn.close()
    if remove_artifacts:
        for run_id in deleted:
            if _remove_artifact_dir(experiment_id, run_id):
                artifacts_removed.append(run_id)
    return {'experiment_id': experiment_id, 'deleted_runs': deleted, 'artifacts_removed': artifacts_removed, 'not_found': not_found}
